ROOT=[dict(id='C0391',meaning='人群；人民；族群与文化',core='ethn-/ethno-：把一群共同生活、认同某些传统的人放在观察中心。',image='先辨认族群身份 ethnic，再走进日常生活去记录 ethnography；若把自己的群体放成唯一标准，就变成 ethnocentrism。',intro='希腊 ethnos 是一群人、人民或族群。ethnic 经宗教语义进入早期英语，后来常用来谈族群文化身份；现代 ethno- 又被用来组成许多社会文化研究名称。',forms='ethnic 加 -ity 成 ethnicity，c 的读音变为 /s/。-graphy 表记录描述，-musicology 表音乐研究，-centric / -centrism 表中心立场。',branches=[['身份与构成','ethnic、ethnicity、ethnically、multiethnic'],['观察文化中的生活','ethnography、ethnographic、ethnomusicology'],['把自己当作衡量标准','ethnocentric、ethnocentrism']],contrasts='ethnic 不等于外国的或少数的，也不自动等于国籍。ethnography 是研究方法，不是对所有族群成员作同一性格判断；ethnocentrism 则常让人忽视文化语境。',practice='分别用 ethnic 与 ethnographic 描述一个社群和一项研究，再写一个 ethnocentric 判断为何需要重新检查。',words=[w for w in family if w not in excluded],exclude=excluded,sources=['https://www.etymonline.com/word/ethnic','https://www.etymonline.com/word/ethnography','https://www.ethnomusicology.org/page/AboutEthnomusicol'])]
